edits.newText:
export function scaledHealth(baseHealth: number, difficulty: Difficulty) {
  return Math.max(1, Math.ceil(baseHealth * difficulty.healthMultiplier))
}

export function clampToPlayableEnvelope(x: number, y: number) {
  return {
    x: Math.min(PLAYABLE_ENVELOPE.maxX, Math.max(PLAYABLE_ENVELOPE.minX, x)),
    y: Math.min(PLAYABLE_ENVELOPE.maxY, Math.max(PLAYABLE_ENVELOPE.minY, y)),
  }
}

export interface AimPoint {
  x: number
  y: number
  z: number
}

/**
 * Deterministic bounded intercept. Error is deliberately applied before the
 * final envelope clamp, so an inaccurate shot can never become unfairly
 * aimed outside the space the player can reach.
 */
export function predictAimTarget(
  player: AimPoint,
  velocity: { x: number; y: number },
  origin: AimPoint,
  difficulty: Difficulty,
  seed: number,
): { x: number; y: number } {
  const range = Math.hypot(player.x - origin.x, player.y - origin.y, player.z - origin.z)
  const interceptTime = Math.min(1.4, Math.max(0.15, range / difficulty.projectileSpeed))
  const lead = interceptTime * difficulty.aimLead
  const boundedSeed = Math.min(1, Math.max(-1, seed))
  const error = 1 - difficulty.accuracy
  return clampToPlayableEnvelope(
    player.x + velocity.x * lead + boundedSeed * 2.4 * error,
    player.y + velocity.y * lead - boundedSeed * 1.6 * error,
  )
}

