interface GameSceneProps {
  flight: FlightRuntime
  running: boolean
  lasers: Map<string, LaserHandle>
  enemies: Map<string, EnemyHandle>
  gameOver: MutableRefObject<boolean>
  enemySpawns: EnemySpawn[]
  laserSpecs: LaserSpec[]
  onEnemyExpired: (spawn: EnemySpawn) => void
  onEnemyFire: (origin: THREE.Vector3, direction: THREE.Vector3, speed: number) => void
  onLaserExpired: (id: string) => void
  registerEnemy: (handle: EnemyHandle) => void
  unregisterEnemy: (id: string) => void
  registerLaser: (handle: LaserHandle) => void
  unregisterLaser: (id: string) => void
  bombs: number
  onBomb: () => void
  onPlayerFire: (origin: THREE.Vector3) => void
  onEncounter: (encounter: Encounter, index: number) => void
  onHitEnemy: (enemyId: string) => void
  onDamagePlayer: (amount: number) => void
  onBarrel: (direction: number) => void
  onStatus: (status: string) => void
  onScore: (amount: number) => void
  onDistance: (distance: number) => void
}

interface SimulationProps {
  flight: FlightRuntime
  running: boolean
  bombs: number
  lasers: Map<string, LaserHandle>
  enemies: Map<string, EnemyHandle>
  gameOver: MutableRefObject<boolean>
  onBomb: () => void
  onPlayerFire: (origin: THREE.Vector3) => void
  onEncounter: (encounter: Encounter, index: number) => void
  onHitEnemy: (enemyId: string) => void
  onDamagePlayer: (amount: number) => void
  onBarrel: (direction: number) => void
  onStatus: (status: string) => void
  onScore: (amount: number) => void
  onDistance: (distance: number) => void
}

function Simulation({ flight, running, bombs, lasers, enemies, gameOver, onBomb, onPlayerFire, onEncounter, onHitEnemy, onDamagePlayer, onBarrel, onStatus, onScore, onDistance }: SimulationProps) {
  const encounterCursor = useRef(0)
  const lastShot = useRef(0)
  const lastHudUpdate = useRef(0)

  useFrame((_, delta) => {
    if (!running || gameOver.current) return
    const { world, player, input } = flight
    world.time += delta
    const now = world.time
    world.boost = input.keys.has('ShiftLeft') || input.keys.has('ShiftRight')
    world.distance += delta * world.speed * (world.boost ? 1.75 : 1)

    while (encounterCursor.current < ENCOUNTERS.length && world.distance >= ENCOUNTERS[encounterCursor.current].at) {
      const index = encounterCursor.current
      onEncounter(ENCOUNTERS[index], index)
      encounterCursor.current += 1
    }

    if (input.justPressed.has('KeyE')) onBarrel(1)
    if (input.justPressed.has('KeyQ') && bombs > 0) onBomb()
    if (input.keys.has('Space') && now - lastShot.current > 0.16) {
      lastShot.current = now
      const origin = player.position.clone()
      origin.z -= 1.2
      onPlayerFire(origin)
    }

    for (const laser of lasers.values()) {
      if (!laser.alive) continue
      if (laser.owner === 'player') {
        for (const enemy of enemies.values()) {
          if (!enemy.alive) continue
          const dx = laser.position.x - enemy.position.x
          const dy = laser.position.y - enemy.position.y
          const dz = Math.abs(laser.position.z - enemy.position.z)
          if (Math.hypot(dx, dy) < enemy.radius && dz < 1.9) {
            laser.alive = false
            onHitEnemy(enemy.id)
            break
          }
        }
